  "ajaccio/sanguinaires": ["Pointe de la Parata and the Sanguinaires", "A path to the Genoese tower, and four islets of red porphyry at sunset."],
  "ajaccio/fesch": ["The Palais Fesch", "The collection of Italian primitives of Cardinal Fesch, Napoleon’s uncle, the richest in France after the Louvre’s."],
  "ajaccio/calanques-piana": ["The Calanques of Piana", "Wind-sculpted red granite plunging into the Gulf of Porto, listed by UNESCO."],
  "ajaccio/marche-ajaccio": ["The Boulevard du Roi-Jérôme market", "Figatellu, brocciu, coppa and Sartène wine, facing the port, under the plane trees."],
  "bastia/citadelle-bastia": ["The citadel and the old port", "Tall, weathered facades around the harbor, and the Genoese town perched above."],
  "bastia/cap-corse": ["Around Cap Corse", "A cliff road, little harbors, Genoese towers, and Nonza on its black rock."],
  "bastia/saint-florent": ["Saint-Florent and Lotu beach", "A boat shuttle to the Agriates desert, and a beach no road reaches."],
  "bastia/oratoire": ["The Oratory of the Immaculate Conception", "A baroque interior of red velvet, where the Anglo-Corsican parliament sat in 1794."],
  "bastia/patrimonio": ["The vineyards of Patrimonio", "Corsica’s first appellation, on the slopes above the Gulf of Saint-Florent."],
  "grenoble/bastille": ["The Bastille “bubbles”", "The cable car with round cabins, a 19th-century fort, and three mountain ranges on the horizon."],
  "grenoble/musee-grenoble": ["The Musée de Grenoble", "One of France’s first modern art museums: Matisse, Picasso, Chagall on the banks of the Isère."],
  "grenoble/chartreuse": ["The Grande Chartreuse", "The monastery can’t be visited; the Correrie museum next door tells of the monks’ silent life."],
  "grenoble/vercors": ["The Vercors and its viewpoints", "A limestone fortress, roads carved into the cliffs, and the Choranche caves."],
  "grenoble/noix": ["Old Grenoble and its walnuts", "Place Saint-André, the oldest café in France, and a walnut cake with protected designation."],
  "brest/oceanopolis": ["Océanopolis", "Three pavilions, three oceans: penguins, sharks and a life-size kelp forest."],
  "brest/saint-mathieu": ["Pointe Saint-Mathieu", "A lighthouse standing in the ruins of an abbey at the end of the land, facing the Iroise islands."],
  "brest/crozon": ["The Crozon peninsula", "Pointe de Pen-Hir, the Tas de Pois, and coastal paths above turquoise water."],
  "brest/chateau-brest": ["The castle and the Naval Museum", "Seventeen centuries of fortifications above the harbor, and models of the French navy’s ships."],
  "brest/ouessant": ["The island of Ouessant", "Two hours by boat, legendary lighthouses, black sheep and wind that never stops."],
  "rennes/parlement": ["The Parliament of Brittany", "The great chamber with its gilded ceilings, restored after the 1994 fire, on a guided tour."],
  "rennes/lices": ["The Lices market", "On Saturday mornings, France’s second-largest market, and a galette-saucisse eaten on the go."],
  "rennes/thabor": ["The Thabor park", "Ten hectares of French formal garden, a rose garden of two thousand varieties and a bandstand."],
  "rennes/broceliande": ["The Brocéliande forest", "Merlin’s tomb, the Barenton spring and the fairy Morgan’s Valley of No Return."],
  "rennes/champs-libres": ["Les Champs Libres", "The Museum of Brittany, a planetarium and a library under one roof by Christian de Portzamparc."],
  "avignon/palais-papes": ["The Palais des Papes", "The largest Gothic palace in the world, home to nine popes in the 14th century."],
  "avignon/pont-avignon": ["The Pont Saint-Bénezet", "Four of its twenty-two arches left, and the song you can’t help humming."],
  "avignon/pont-du-gard": ["The Pont du Gard", "A forty-eight-meter Roman aqueduct, and a swim in the Gardon right below it."],
  "avignon/gordes": ["Gordes and the Luberon", "A hilltop village of dry stone, Sénanque Abbey and its lavender in July."],
  "avignon/chateauneuf": ["Châteauneuf-du-Pape", "Rounded pebbles at the foot of the vines, and tastings in the cellars of the popes’ wine."],
  "avignon/halles-avignon": ["Les Halles d’Avignon", "A living plant wall outside, and inside olives, Cavaillon melons and goat cheese."],
  "la-rochelle/vieux-port": ["The Old Port and its towers", "The Chain Tower and the Saint-Nicolas Tower that guarded the harbor, and the Lantern a little further on."],
  "la-rochelle/aquarium": ["The La Rochelle Aquarium", "Twelve thousand marine animals, jellyfish in the dark and a tunnel beneath the sharks."],
  "la-rochelle/ile-re": ["Île de Ré by bike", "A hundred kilometers of cycle paths, salt marshes, Saint-Martin and its Vauban fortifications."],
  "la-rochelle/fort-boyard": ["Fort Boyard by boat", "You don’t land: you circle the stone fort standing in the Pertuis d’Antioche."],
  "la-rochelle/arcades": ["The arcades and the central market", "Arcaded streets for strolling in the shade, and Marennes oysters at the market."],
  "carcassonne/cite": ["The Cité of Carcassonne", "Three kilometers of ramparts, fifty-two towers, and the count’s castle restored by Viollet-le-Duc."],
  "carcassonne/cassoulet": ["Cassoulet in the Cité", "Lingot beans, confit and Toulouse sausage, slow-cooked in the earthenware cassole."],
  "carcassonne/canal-carcassonne": ["The Canal du Midi by boat", "Two locks and the plane trees, on Riquet’s UNESCO-listed waterway."],
