/** Les phrases du carnet, clé française normalisée → anglais, prêtes pour le dictionnaire. */
export function phrasesDuCarnet(): Record<string, string> {
  const phrases: Record<string, string> = {};
  for (const activite of ACTIVITES) {
    const anglais = NOMS_ET_RESUMES[activite.id];
    if (!anglais) continue;
    phrases[normaliser(activite.nom)] = anglais[0];
    phrases[normaliser(activite.resume)] = anglais[1];
  }
  return phrases;
}
